*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{font-family:'Montserrat',sans-serif;color:#111;background:#fff;overflow-x:hidden}

/* ── SAND CANVAS ─────────────────────────── */
#sand-canvas{position:fixed;inset:0;z-index:0;pointer-events:none}

/* ── NAV ────────────────────────────────── */
nav{position:fixed;top:0;left:0;right:0;z-index:200;background:rgba(255,255,255,.9);backdrop-filter:blur(24px);border-bottom:1px solid #e8e8e8;transition:box-shadow .3s}
nav.scrolled{box-shadow:0 4px 32px rgba(0,0,0,.08)}
.nav-link{position:relative;color:#555;font-weight:600;font-size:.8rem;text-transform:uppercase;letter-spacing:.08em;transition:color .2s;text-decoration:none}
.nav-link::after{content:'';position:absolute;bottom:-3px;left:0;width:0;height:2px;background:#FF9900;transition:width .3s}
.nav-link:hover{color:#FF9900}
.nav-link:hover::after{width:100%}

/* ── HERO ───────────────────────────────── */
.hero-wrap{position:relative;overflow:hidden;min-height:100vh;display:flex;align-items:center;z-index:1}
.hero-wrap::before{content:'';position:absolute;inset:0;background-image:url('data:image/jpeg;base64,');background-size:cover;background-position:center 30%;filter:brightness(.15);z-index:0}
.hero-wrap::after{content:'';position:absolute;inset:0;background:linear-gradient(120deg,rgba(0,0,0,.8) 0%,rgba(0,0,0,.3) 60%,rgba(0,0,0,.05) 100%);z-index:1}
.hero-inner{position:relative;z-index:2}

/* ── EFFECT 1: OUTLINED STROKE TEXT ─────── */
.text-stroke{
  font-family:'Bebas Neue',sans-serif;
  -webkit-text-stroke:2px #FF9900;
  color:transparent;
  line-height:.9;
  letter-spacing:2px;
}
/* ── EFFECT 2: GRADIENT FILL TEXT ───────── */
.text-gradient{
  font-family:'Bebas Neue',sans-serif;
  background:linear-gradient(135deg,#fff 0%,#FF9900 45%,#fff 100%);
  background-size:300% auto;
  -webkit-background-clip:text;
  -webkit-text-fill-color:transparent;
  background-clip:text;
  animation:gradientShift 4s ease-in-out infinite alternate;
  line-height:.9;
  letter-spacing:2px;
}
@keyframes gradientShift{
  0%{background-position:0% center}
  100%{background-position:100% center}
}

/* ── EFFECT 3: GLITCH TEXT ───────────────── */
.glitch{
  font-family:'Bebas Neue',sans-serif;
  color:#fff;
  position:relative;
  letter-spacing:3px;
}
.glitch::before,.glitch::after{
  content:attr(data-text);
  position:absolute;
  top:0;left:0;width:100%;height:100%;
  font-family:'Bebas Neue',sans-serif;
  letter-spacing:3px;
}
.glitch::before{color:#FF9900;animation:glitch1 3s infinite linear;clip-path:polygon(0 0,100% 0,100% 45%,0 45%)}
.glitch::after{color:#00cfff;animation:glitch2 3s infinite linear;clip-path:polygon(0 55%,100% 55%,100% 100%,0 100%)}
@keyframes glitch1{
  0%,85%,100%{transform:translate(0)}
  86%{transform:translate(-3px,1px)}
  88%{transform:translate(3px,-1px)}
  90%{transform:translate(-2px,2px)}
  92%{transform:translate(0)}
}
@keyframes glitch2{
  0%,85%,100%{transform:translate(0)}
  87%{transform:translate(3px,-1px)}
  89%{transform:translate(-3px,1px)}
  91%{transform:translate(2px,-2px)}
  93%{transform:translate(0)}
}

/* ── EFFECT 4: NEON GLOW TEXT ────────────── */
.text-neon{
  font-family:'Bebas Neue',sans-serif;
  color:#FF9900;
  text-shadow:0 0 8px rgba(255,153,0,.8),0 0 20px rgba(255,153,0,.5),0 0 40px rgba(255,153,0,.3);
  animation:neonPulse 2.5s ease-in-out infinite alternate;
  letter-spacing:3px;
}
@keyframes neonPulse{
  0%{text-shadow:0 0 8px rgba(255,153,0,.8),0 0 20px rgba(255,153,0,.5),0 0 40px rgba(255,153,0,.3)}
  100%{text-shadow:0 0 14px rgba(255,153,0,1),0 0 32px rgba(255,153,0,.7),0 0 60px rgba(255,153,0,.4),0 0 80px rgba(255,153,0,.2)}
}

/* ── TRUST BOXES ─────────────────────────── */
.trust-box{background:#fff;border-radius:1.25rem;border:1px solid #e8e8e8;padding:1.5rem;text-align:center;transition:all .4s cubic-bezier(.16,1,.3,1);position:relative;overflow:hidden}
.trust-box::before{content:'';position:absolute;inset:0;background:radial-gradient(circle at var(--mx,50%) var(--my,50%),rgba(255,153,0,.1) 0%,transparent 60%);opacity:0;transition:opacity .3s}
.trust-box:hover{transform:translateY(-6px) scale(1.02);box-shadow:0 20px 48px rgba(255,153,0,.15);border-color:rgba(255,153,0,.35)}
.trust-box:hover::before{opacity:1}
.trust-icon{font-size:2rem;margin-bottom:.75rem;display:block;transition:transform .4s cubic-bezier(.16,1,.3,1)}
.trust-box:hover .trust-icon{transform:scale(1.2) rotate(-6deg)}

/* ── PHONE CARDS ─────────────────────────── */
.phone-card{background:#fff;border-radius:1.5rem;border:1px solid #e8e8e8;overflow:hidden;transition:box-shadow .4s;position:relative}
.phone-card::after{content:'';position:absolute;inset:0;border-radius:1.5rem;box-shadow:inset 0 0 0 2px rgba(255,153,0,0);transition:box-shadow .3s;pointer-events:none}
.phone-card:hover::after{box-shadow:inset 0 0 0 2px rgba(255,153,0,.7)}
.phone-img-wrap{background:linear-gradient(135deg,#f8f8f8,#efefef);height:13rem;display:flex;align-items:center;justify-content:center;padding:1.5rem;overflow:hidden}
.phone-img{max-height:11rem;object-fit:contain;transition:transform .5s cubic-bezier(.16,1,.3,1),filter .4s}
.phone-card:hover .phone-img{transform:scale(1.1) translateY(-6px);filter:drop-shadow(0 16px 24px rgba(0,0,0,.2))}

/* ── REVEAL ──────────────────────────────── */
.reveal{opacity:0;transform:translateY(32px);transition:opacity .75s ease,transform .75s cubic-bezier(.16,1,.3,1)}
.reveal.visible{opacity:1;transform:translateY(0)}
.rv1{transition-delay:.1s}.rv2{transition-delay:.2s}.rv3{transition-delay:.3s}.rv4{transition-delay:.4s}

/* ── EFFECT 5: COUNTER NUMBERS ───────────── */
.count-num{
  font-family:'Bebas Neue',sans-serif;
  font-size:3rem;
  color:#FF9900;
  letter-spacing:2px;
  transition:all .3s;
}
.stat-card{background:#fff;border:1px solid #e8e8e8;border-radius:1.25rem;padding:1.5rem 2rem;text-align:center;transition:all .35s cubic-bezier(.16,1,.3,1)}
.stat-card:hover{transform:translateY(-4px);border-color:#FF9900;box-shadow:0 12px 40px rgba(255,153,0,.12)}

/* ── BTNS ────────────────────────────────── */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:.5rem;font-weight:700;border-radius:.875rem;transition:all .25s;cursor:pointer;text-decoration:none;font-family:'Montserrat',sans-serif;text-transform:uppercase;letter-spacing:.05em;font-size:.85rem}
.btn-orange{background:#FF9900;color:#fff;padding:.875rem 2rem;position:relative;overflow:hidden}
.btn-orange::before{content:'';position:absolute;inset:0;background:linear-gradient(45deg,transparent 30%,rgba(255,255,255,.25) 50%,transparent 70%);transform:translateX(-100%);transition:transform .5s}
.btn-orange:hover{background:#e68a00;transform:translateY(-2px);box-shadow:0 0 0 4px rgba(255,153,0,.2),0 12px 32px rgba(255,153,0,.4)}
.btn-orange:hover::before{transform:translateX(100%)}
.btn-ghost{border:2px solid rgba(255,255,255,.35);color:#fff;padding:.875rem 2rem}
.btn-ghost:hover{border-color:#FF9900;color:#FF9900}

/* ── REVIEW CARDS ────────────────────────── */
.review-card{background:#fff;border-radius:1.25rem;border:1px solid #e8e8e8;padding:1.5rem;transition:all .35s cubic-bezier(.16,1,.3,1);position:relative;overflow:hidden}
.review-card::before{content:'';position:absolute;inset:0;background:radial-gradient(circle at var(--mx,50%) var(--my,50%),rgba(255,153,0,.07) 0%,transparent 65%);opacity:0;transition:opacity .3s;pointer-events:none}
.review-card:hover{transform:translateY(-5px);box-shadow:0 20px 56px rgba(0,0,0,.09);border-color:rgba(255,153,0,.25)}
.review-card:hover::before{opacity:1}

/* ── MARQUEE ─────────────────────────────── */
@keyframes marquee{0%{transform:translateX(0)}100%{transform:translateX(-50%)}}
.marquee-track{display:flex;animation:marquee 20s linear infinite;width:max-content}
.marquee-track:hover{animation-play-state:paused}

.section-tag{display:inline-block;background:#fff3e0;color:#FF9900;font-size:.65rem;font-weight:700;text-transform:uppercase;letter-spacing:.12em;padding:.3rem 1rem;border-radius:100px;margin-bottom:1rem}
.canje-section{background:#f5f5f7}
.mob-menu{display:none}
.mob-menu.open{display:flex}

/* ── ACC CARDS ───────────────────────────── */
.acc-card{
  background:#1c1c1e;
  border:1px solid #333;
  border-radius:1.5rem;
  overflow:hidden;
  position:relative;
  transition:all .4s cubic-bezier(.16,1,.3,1);
  cursor:default;
}
.acc-card::before{
  content:'';
  position:absolute;
  inset:0;
  background:radial-gradient(circle at var(--mx,50%) var(--my,50%),rgba(255,153,0,.12) 0%,transparent 55%);
  opacity:0;
  transition:opacity .3s;
  z-index:1;
  pointer-events:none;
}
.acc-card:hover{
  transform:translateY(-10px) scale(1.02);
  border-color:rgba(255,153,0,.5);
  box-shadow:0 0 0 1px rgba(255,153,0,.3),0 24px 60px rgba(0,0,0,.5),0 0 60px rgba(255,153,0,.08);
}
.acc-card:hover::before{opacity:1}
.acc-img-wrap{
  height:14rem;
  display:flex;
  align-items:center;
  justify-content:center;
  padding:2rem;
  background:linear-gradient(135deg,#222 0%,#1a1a1a 100%);
  position:relative;
  overflow:hidden;
}
.acc-img-wrap::after{
  content:'';
  position:absolute;
  inset:0;
  background:radial-gradient(circle at 50% 100%,rgba(255,153,0,.06) 0%,transparent 70%);
  pointer-events:none;
}
.acc-img{
  max-height:11rem;
  max-width:11rem;
  object-fit:contain;
  filter:drop-shadow(0 8px 24px rgba(0,0,0,.6));
  transition:transform .5s cubic-bezier(.16,1,.3,1),filter .4s;
  position:relative;
  z-index:1;
}
.acc-card:hover .acc-img{
  transform:scale(1.12) translateY(-8px) rotate(2deg);
  filter:drop-shadow(0 16px 32px rgba(255,153,0,.2));
}
/* shine sweep */
.acc-shine{
  position:absolute;
  top:0;left:-100%;
  width:60%;height:100%;
  background:linear-gradient(90deg,transparent,rgba(255,255,255,.06),transparent);
  transform:skewX(-15deg);
  transition:left .6s ease;
  pointer-events:none;
  z-index:3;
}
.acc-card:hover .acc-shine{left:150%}
.acc-tag{
  display:inline-block;
  font-size:.65rem;
  font-weight:700;
  text-transform:uppercase;
  letter-spacing:.1em;
  padding:.25rem .75rem;
  border-radius:100px;
  background:rgba(255,255,255,.08);
  color:#aaa;
  border:1px solid #444;
  margin-bottom:.5rem;
}
.acc-tag-featured{
  background:rgba(255,153,0,.15);
  color:#FF9900;
  border-color:rgba(255,153,0,.3);
}
.acc-title{
  font-family:'Bebas Neue',sans-serif;
  font-size:1.3rem;
  letter-spacing:2px;
  color:#fff;
  margin-bottom:.3rem;
}
.acc-sub{
  font-size:.7rem;
  color:#555;
  font-weight:500;
  margin-bottom:1rem;
  line-height:1.5;
}
.acc-btn{
  display:flex;
  align-items:center;
  justify-content:center;
  width:100%;
  padding:.625rem 1rem;
  background:#FF9900;
  color:#fff;
  font-family:'Montserrat',sans-serif;
  font-size:.7rem;
  font-weight:700;
  text-transform:uppercase;
  letter-spacing:.06em;
  border-radius:.625rem;
  text-decoration:none;
  transition:all .25s;
  position:relative;
  overflow:hidden;
}
.acc-btn::before{
  content:'';
  position:absolute;
  inset:0;
  background:linear-gradient(45deg,transparent 30%,rgba(255,255,255,.2) 50%,transparent 70%);
  transform:translateX(-100%);
  transition:transform .4s;
}
.acc-btn:hover{background:#e68a00;box-shadow:0 0 20px rgba(255,153,0,.4)}
.acc-btn:hover::before{transform:translateX(100%)}


/* ── NEW ACC CARDS ──────────────────────────────── */
.newacc-card{
  background:#1c1c1e;
  border-radius:1.5rem;
  border:1px solid rgba(255,255,255,.08);
  overflow:hidden;
  position:relative;
  transition:all .45s cubic-bezier(.16,1,.3,1);
  cursor:default;
}
.newacc-card:hover{
  transform:translateY(-10px) scale(1.02);
  border-color:rgba(255,153,0,.45);
  box-shadow:0 0 0 1px rgba(255,153,0,.2),
             0 28px 64px rgba(0,0,0,.6),
             0 0 48px rgba(255,153,0,.08);
}
.newacc-featured{
  border-color:rgba(255,153,0,.2);
}
/* spotlight glow */
.newacc-glow{
  position:absolute;inset:0;border-radius:1.5rem;
  background:radial-gradient(circle at var(--mx,50%) var(--my,50%),rgba(255,153,0,.13) 0%,transparent 55%);
  opacity:0;transition:opacity .3s;pointer-events:none;z-index:1;
}
.newacc-card:hover .newacc-glow{opacity:1}

/* image area */
.newacc-img-area{
  height:14rem;
  display:flex;align-items:center;justify-content:center;
  background:linear-gradient(160deg,#232323 0%,#191919 100%);
  position:relative;z-index:2;
  border-bottom:1px solid rgba(255,255,255,.06);
}
.newacc-img-area::after{
  content:'';position:absolute;inset:0;
  background:radial-gradient(circle at 50% 90%,rgba(255,153,0,.07) 0%,transparent 65%);
  pointer-events:none;
}

/* ring system */
.newacc-ring{
  position:relative;
  width:8.5rem;height:8.5rem;
  display:flex;align-items:center;justify-content:center;
}
.newacc-ring-spin{
  position:absolute;inset:-4px;
  border-radius:50%;
  border:2px dashed rgba(255,153,0,.2);
  animation:accSpin 10s linear infinite;
  transition:border-color .4s,animation-duration .4s;
}
.newacc-card:hover .newacc-ring-spin{
  border-color:rgba(255,153,0,.55);
  animation-duration:3s;
}
@keyframes accSpin{0%{transform:rotate(0deg)}100%{transform:rotate(360deg)}}

.newacc-ring-inner{
  width:8.5rem;height:8.5rem;border-radius:50%;
  background:linear-gradient(135deg,#2a2a2a,#1e1e1e);
  border:2px solid rgba(255,255,255,.08);
  box-shadow:0 0 0 4px #1c1c1e,
             0 0 0 5px rgba(255,255,255,.05),
             inset 0 0 24px rgba(0,0,0,.5);
  display:flex;align-items:center;justify-content:center;
  position:relative;z-index:2;
  transition:all .4s cubic-bezier(.16,1,.3,1);
}
.newacc-card:hover .newacc-ring-inner{
  border-color:rgba(255,153,0,.5);
  box-shadow:0 0 0 4px #1c1c1e,
             0 0 0 5px rgba(255,153,0,.25),
             0 0 28px rgba(255,153,0,.18),
             inset 0 0 24px rgba(0,0,0,.5);
}
.newacc-ring-gold .newacc-ring-inner{
  border-color:rgba(255,153,0,.3);
  box-shadow:0 0 0 4px #1c1c1e,
             0 0 0 5px rgba(255,153,0,.15),
             0 0 16px rgba(255,153,0,.12),
             inset 0 0 24px rgba(0,0,0,.5);
}
.newacc-ring-gold .newacc-ring-spin{
  border-color:rgba(255,153,0,.35);
  animation-duration:6s;
}

.newacc-img{
  max-height:6rem;max-width:6rem;
  object-fit:contain;
  filter:drop-shadow(0 4px 12px rgba(0,0,0,.6));
  transition:transform .5s cubic-bezier(.16,1,.3,1),filter .4s;
}
.newacc-card:hover .newacc-img{
  transform:scale(1.15) translateY(-3px);
  filter:drop-shadow(0 8px 20px rgba(255,153,0,.25));
}

/* body */
.newacc-body{padding:1.25rem;position:relative;z-index:2}
.newacc-badge{
  display:inline-block;
  font-size:.6rem;font-weight:700;text-transform:uppercase;letter-spacing:.1em;
  padding:.2rem .75rem;border-radius:100px;
  background:rgba(255,255,255,.06);color:#888;
  border:1px solid rgba(255,255,255,.1);
  margin-bottom:.5rem;
}
.newacc-badge-gold{
  background:rgba(255,153,0,.15);color:#FF9900;
  border-color:rgba(255,153,0,.3);
}
.newacc-title{
  font-family:'Bebas Neue',sans-serif;
  font-size:1.15rem;letter-spacing:2px;
  color:#fff;margin-bottom:.3rem;
}
.newacc-sub{
  font-size:.7rem;color:#777;font-weight:500;
  margin-bottom:1rem;line-height:1.5;
}

/* shine sweep */
.newacc-shine{
  position:absolute;top:0;left:-100%;width:55%;height:100%;
  background:linear-gradient(90deg,transparent,rgba(255,255,255,.05),transparent);
  transform:skewX(-15deg);transition:left .65s ease;
  pointer-events:none;z-index:5;
}
.newacc-card:hover .newacc-shine{left:160%}

/* btn */
.newacc-btn{
  display:flex;align-items:center;justify-content:center;
  width:100%;padding:.625rem 1rem;
  background:#FF9900;color:#fff;
  font-family:'Montserrat',sans-serif;font-size:.7rem;font-weight:700;
  text-transform:uppercase;letter-spacing:.06em;
  border-radius:.625rem;text-decoration:none;
  transition:all .25s;position:relative;overflow:hidden;
}
.newacc-btn::before{
  content:'';position:absolute;inset:0;
  background:linear-gradient(45deg,transparent 30%,rgba(255,255,255,.2) 50%,transparent 70%);
  transform:translateX(-100%);transition:transform .4s;
}
.newacc-btn:hover{background:#e68a00;box-shadow:0 0 20px rgba(255,153,0,.4)}
.newacc-btn:hover::before{transform:translateX(100%)}

@keyframes acSpin{0%{transform:rotate(0deg)}100%{transform:rotate(360deg)}}
.ac:hover{transform:translateY(-10px) scale(1.015);
           border-color:rgba(255,153,0,.5)!important;
           box-shadow:0 0 0 1px rgba(255,153,0,.2),0 28px 64px rgba(0,0,0,.6),0 0 48px rgba(255,153,0,.07)!important}
.ac:hover .ac-glow{opacity:1!important}
.ac:hover .ac-shine{left:160%!important}
.ac:hover .ac-disk{border-color:rgba(255,153,0,.55)!important;
  box-shadow:0 0 0 5px #1c1c1e,0 0 0 6px rgba(255,153,0,.28),0 0 28px rgba(255,153,0,.18),inset 0 0 20px rgba(0,0,0,.5)!important}
.ac:hover .ac-spin{border-color:rgba(255,153,0,.6)!important;animation-duration:3s!important}
.ac:hover .ac-img{transform:scale(1.18) translateY(-4px)!important;
  filter:drop-shadow(0 8px 20px rgba(255,153,0,.3))!important}
.ac-btn:hover{background:#e68a00!important;box-shadow:0 0 20px rgba(255,153,0,.4)!important}


/* ── PREMIUM UI ELEMENTS ───────────────────────────── */
body, a, button, .btn, .ac-btn, .nav-link { cursor: none !important; }

/* Preloader */
.preloader {
  position: fixed; top: 0; left: 0; width: 100%; height: 100%;
  background: #000; z-index: 99999;
  display: flex; align-items: center; justify-content: center;
  transition: opacity 0.8s cubic-bezier(0.16, 1, 0.3, 1), visibility 0.8s;
}
.preloader.hidden { opacity: 0; visibility: hidden; }
.loader-text {
  font-family: 'Bebas Neue', sans-serif;
  font-size: 3rem; color: #fff; letter-spacing: 4px;
  animation: pulseLoader 1.5s infinite alternate;
}
@keyframes pulseLoader { 0% { opacity: 0.3; transform: scale(0.98); } 100% { opacity: 1; transform: scale(1); } }

/* Scroll Progress */
.scroll-progress {
  position: fixed; top: 0; left: 0; height: 3px; background: #FF9900;
  width: 0%; z-index: 99998; pointer-events: none;
  transition: width 0.1s ease-out;
  box-shadow: 0 0 10px rgba(255,153,0,0.5);
}

/* Custom Cursor */
.cursor-dot {
  position: fixed; top: 0; left: 0; width: 6px; height: 6px;
  background: #FF9900; border-radius: 50%;
  transform: translate(-50%, -50%);
  pointer-events: none; z-index: 100000;
  transition: width 0.2s, height 0.2s, background 0.2s;
}
.cursor-ring {
  position: fixed; top: 0; left: 0; width: 36px; height: 36px;
  border: 1px solid rgba(255,153,0,0.5); border-radius: 50%;
  transform: translate(-50%, -50%);
  pointer-events: none; z-index: 99999;
  transition: width 0.3s, height 0.3s, border-color 0.3s;
}
.cursor-hover .cursor-dot { width: 40px; height: 40px; background: rgba(255,153,0,0.1); border: 1px solid rgba(255,153,0,0.3); mix-blend-mode: difference; }
.cursor-hover .cursor-ring { width: 60px; height: 60px; border-color: transparent; }

/* Grain Overlay */
.grain-overlay {
  position: fixed; top: 0; left: 0; width: 100vw; height: 100vh;
  pointer-events: none; z-index: 99997; opacity: 0.05;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E");
}

/* Magnetic Items */
.magnetic { display: inline-block; transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1); }

